	/**
	 * An icon.
	 *
	 * @param string $name   Icon name.
	 * @param string $stroke Stroke width.
	 * @param string $css    Extra class.
	 * @return string SVG markup.
	 */
	public static function get( $name, $stroke = '1.75', $css = '' ) {
		if ( ! isset( self::PATHS[ $name ] ) ) {
			return '';
		}

		return '<svg' . ( $css ? ' class="' . esc_attr( $css ) . '"' : '' ) . ' viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' . esc_attr( $stroke ) . '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="' . esc_attr( self::PATHS[ $name ] ) . '"/></svg>';
	}

	/**
	 * The WPHEKA menu icon: the ring, and the W with the plug growing from its middle
	 * peak, drawn as filled shapes on WordPress's 20px menu-icon grid. One joined mark,
	 * so it does not read as two letters at 20px.
	 *
	 * Returned as a base64 data URI with fill #a7aaad, so WordPress's svg-painter
	 * repaints it in each admin colour scheme (grey, hover blue, current white), as it
	 * does its own icons. A file URL would stay one colour.
	 *
	 * @return string Data URI.
	 */
	public static function menu_icon() {
		$svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path fill="#a7aaad" fill-rule="evenodd" d="M10 0.00a10 10 0 1 0 0 20a10 10 0 1 0 0 -20Z M10 1.50a8.5 8.5 0 1 1 0 17.0a8.5 8.5 0 1 1 0 -17.0Z"/><path fill="#a7aaad" d="M3.11 7.53 L6.78 17.42 L10.85 9.01 L9.15 8.19 L7.02 12.58 L4.89 6.87 Z"/><path fill="#a7aaad" d="M9.15 9.01 L13.22 17.42 L16.89 7.53 L15.11 6.87 L12.98 12.58 L10.85 8.19 Z"/><path fill="#a7aaad" d="M8.5 3.5h1v2h-1Z"/><path fill="#a7aaad" d="M10.5 3.5h1v2h-1Z"/><path fill="#a7aaad" d="M7.75 5.5h4.5v2.5h-4.5Z"/><path fill="#a7aaad" d="M7.75 7.9H12.25A2.25 2.4 0 0 1 7.75 7.9Z"/></svg>';

		return 'data:image/svg+xml;base64,' . base64_encode( $svg ); // phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions.obfuscation_base64_encode -- WordPress menu icons take an SVG data URI.
	}

	/**
	 * The WPHEKA mark in the brand gradient.
	 *
	 * @return string SVG markup.
	 */
	public static function logo() {
		$g = 'wpheka-ui-logo-' . wp_rand( 1000, 9999 );

		return '<svg viewBox="0 0 100 100" fill="none" aria-hidden="true" focusable="false"><defs><linearGradient id="' . $g . '" x1="0" y1="0" x2="100" y2="100" gradientUnits="userSpaceOnUse"><stop offset="0%" stop-color="#a78bfa"/><stop offset="30%" stop-color="#7c3aed"/><stop offset="100%" stop-color="#26bd6c"/></linearGradient></defs><circle cx="50" cy="50" r="45" stroke="url(#' . $g . ')" stroke-width="6"/><path d="M22 35 35 75 48 45" stroke="url(#' . $g . ')" stroke-width="8" stroke-linejoin="round" stroke-linecap="round"/><path d="M52 45 65 75 78 35" stroke="url(#' . $g . ')" stroke-width="8" stroke-linejoin="round" stroke-linecap="round"/><rect x="42" y="18" width="4" height="16" rx="2" fill="url(#' . $g . ')"/><rect x="54" y="18" width="4" height="16" rx="2" fill="url(#' . $g . ')"/><rect x="34" y="34" width="32" height="5" rx="1" fill="url(#' . $g . ')"/><path d="M38 39H62V50C62 56 57 60 50 60 43 60 38 56 38 50Z" fill="url(#' . $g . ')"/></svg>';
	}
